        Gradebook book = new Gradebook();
        Student a = new Student("Student One");
        a.addScore(90);
        a.addScore(80);
        book.enroll(a);
        System.out.printf("Class average: %.1f%n", book.classAverage());
        System.out.println("Passing: " + book.passingCount());
    }
}

